const items = $input.all();
const processedItems = [];

for (const item of items) {
  const data = item.json;

  const property = {
    id: data.id || data.exposeid || `PROP-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    source: data.source || 'Unknown',
    title: data.title || data.name || 'Property Listing',
    address: data.address || data.location || 'Address not provided',
    city: data.city || data.place || 'Unknown',
    price: parseFloat(data.price || data.purchasePrice || 0),
    rent: parseFloat(data.rent || data.rentPerMonth || 0),
    size: parseFloat(data.size || data.livingSpace || 0),
    rooms: parseFloat(data.rooms || data.numberOfRooms || 0),
    yearBuilt: parseInt(data.yearBuilt || data.constructionYear || 0),
    propertyType: data.propertyType || data.type || 'Apartment',
    condition: data.condition || 'Not specified',
    agentName: data.agentName || data.contact?.name || 'Agent',
    agentEmail: data.agentEmail || data.contact?.email || 'agent@example.com',
    agentPhone: data.agentPhone || data.contact?.phone || '',
    listingUrl: data.url || data.link || '',
    description: data.description || '',
    fetchedAt: new Date().toISOString()
  };

  const roi = property.rent > 0 && property.price > 0 ? ((property.rent * 12) / property.price) * 100 : 0;
  const pricePerSqm = property.size > 0 ? property.price / property.size : 0;

  let score = 50;

  if (roi >= 8) score += 30;
  else if (roi >= 6) score += 20;
  else if (roi >= 4) score += 10;

  if (property.price < 200000) score += 20;
  else if (property.price < 350000) score += 15;
  else if (property.price < 500000) score += 10;

  if (property.condition.toLowerCase().includes('renovated') || property.condition.toLowerCase().includes('new')) {
    score += 15;
  } else if (property.condition.toLowerCase().includes('good')) {
    score += 10;
  }

  const age = new Date().getFullYear() - property.yearBuilt;
  if (age < 10) score += 15;
  else if (age < 30) score += 10;
  else if (age < 50) score += 5;

  if (property.size >= 100) score += 10;
  else if (property.size >= 70) score += 7;
  else if (property.size >= 50) score += 5;

  const premiumCities = ['Berlin', 'Munich', 'Hamburg', 'Frankfurt', 'Stuttgart'];
  if (premiumCities.some(city => property.city.includes(city))) {
    score += 10;
  }

  property.roi = parseFloat(roi.toFixed(2));
  property.pricePerSqm = parseFloat(pricePerSqm.toFixed(2));
  property.score = Math.min(100, Math.max(0, score));
  property.scoreCategory = score >= 80 ? 'Excellent' : score >= 60 ? 'Good' : score >= 40 ? 'Fair' : 'Poor';

  processedItems.push({ json: property });
}

return processedItems;

const items = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

const todayListings = items.filter(item => {
  const fetchedDate = new Date(item.json.fetchedAt);
  fetchedDate.setHours(0, 0, 0, 0);
  return fetchedDate.getTime() === today.getTime();
});

const totalListings = items.length;
const newListingsToday = todayListings.length;
const emailsSent = items.filter(item => item.json.emailSent === 'Yes').length;

const sortedByScore = [...items].sort((a, b) => parseFloat(b.json.score || 0) - parseFloat(a.json.score || 0));
const top5Properties = sortedByScore.slice(0, 5);

const avgPrice = items.reduce((sum, item) => sum + parseFloat(item.json.price || 0), 0) / items.length;
const avgRoi = items.reduce((sum, item) => sum + parseFloat(item.json.roi || 0), 0) / items.length;

return [{
  json: {
    reportDate: new Date().toISOString(),
    totalListings,
    newListingsToday,
    emailsSent,
    avgPrice: parseFloat(avgPrice.toFixed(2)),
    avgRoi: parseFloat(avgRoi.toFixed(2)),
    top5Properties: top5Properties.map(item => ({
      title: item.json.title,
      city: item.json.city,
      price: item.json.price,
      roi: item.json.roi,
      score: item.json.score
    }))
  }
}];
